// The AI node returns the parsed JSON fields, or { text } if the model's answer was not valid JSON.
// If the AI fails, the email still goes to support so a person sees it.
// The holding reply is a fixed template (not AI text), so it can never promise refunds, dates or fixes.
const email = $('Settings').item.json;
let ai = $json;
if (typeof ai.category !== 'string') {
  try {
    ai = JSON.parse(ai.text);
  } catch {
    ai = {};
  }
}

const teams = {
  support: { label: 'Support', to: email.supportEmail },
  sales: { label: 'Sales', to: email.salesEmail },
  billing: { label: 'Billing', to: email.billingEmail },
  spam: { label: 'Spam', to: null },
};
const category = teams[String(ai.category).toLowerCase()] ? String(ai.category).toLowerCase() : 'support';

// "Lena Fischer <lena@shop.test>" -> name + address
const from = String(email.from || '');
const address = (from.match(/<([^>]+)>/) || [, from])[1].trim();
const name = from.replace(/<[^>]*>/, '').replace(/"/g, '').trim() || address;

const firstName = name.split(/\s+/)[0];
const topic = String(ai.topic || '').trim();
const replyDraft = topic && category !== 'spam'
  ? `Hi ${firstName},\n\nThanks for your email about ${topic}. Our ${teams[category].label.toLowerCase()} team will get back to you shortly.\n\nThe ${email.companyName} team`
  : '';

return {
  json: {
    fromName: name,
    fromEmail: address,
    subject: email.subject || '(no subject)',
    body: email.textPlain || email.textHtml || '',
    category,
    team: teams[category].label,
    routeTo: teams[category].to,
    urgent: String(ai.urgency).toLowerCase() === 'urgent',
    aiUsed: typeof ai.summary === 'string' && ai.summary.trim() !== '',
    summary: ai.summary || 'The AI could not read this email. Please check it yourself.',
    replyDraft,
    managerEmail: email.managerEmail,
    botEmail: email.botEmail,
    companyName: email.companyName,
  },
};

